package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import com.lianxibu.site.repository.jobs.JdbcBacklogMutationWitness;import org.junit.jupiter.api.Test;
class SharedWriteHostMemoryWitnessTest extends SharedWriteMutationWitnessTest {
 @Test void exactNativeHostMemoryObservationInitializesThenPreservesBusinessWitness(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){write(f,"collector-host-memory:"+"a".repeat(64),"collector-host-memory");var original=read(f,scope);assertEquals(0,original.sequence());f.clock.now=f.clock.now.plusSeconds(60);write(f,"fictional-real-business","fictional-business");var business=read(f,scope);assertEquals(1,business.sequence());f.clock.now=f.clock.now.plusSeconds(60);write(f,"collector-host-memory:"+"b".repeat(64),"collector-host-memory");assertEquals(business,read(f,scope));assertEquals(3,f.sql.queryForObject("SELECT fictional_marker FROM worker_lock",Integer.class));}}
 @Test void nativeHashShapeResourceAndExactActionAllRequiredForObservationExclusion(){var f=fixture();try(var scope=JdbcBacklogMutationWitness.open(f.source,f.clock)){String valid="collector-host-memory:"+"c".repeat(64);write(f,valid,"fictional-business");assertEquals(1,read(f,scope).sequence());write(f,"collector-host-memory:"+"c".repeat(63),"collector-host-memory");assertEquals(2,read(f,scope).sequence());write(f,valid+":1","collector-host-memory");assertEquals(3,read(f,scope).sequence());write(f,"collector-host-memory:"+"C".repeat(64),"collector-host-memory");assertEquals(4,read(f,scope).sequence());write(f,"fictional-other-telemetry:"+"d".repeat(64),"collector-host-memory");assertEquals(5,read(f,scope).sequence());write(f,valid,"collector-host-memory");assertEquals(5,read(f,scope).sequence());}}
}
